object ExamQuestionBank {
    private val allByChapter: Map<String, List<ExamQuestion>> by lazy {
        ExamBankPart1.questions + ExamBankPart2.questions + ExamBankPart3.questions
    }

    private val allById: Map<String, ExamQuestion> by lazy {
        allByChapter.values.flatten().associateBy { it.id }
    }

    fun getQuestionsForChapter(
        subjectId: String,
        chapterId: String,
        chapterTitle: String,
        paper: Int
    ): List<ExamQuestion> {
        val exact = allByChapter[chapterId]
        if (!exact.isNullOrEmpty()) return exact

        // Graceful 3-question bank for any custom-added chapter
        val paperLabel = if (paper == 1) "১ম পত্র" else "২য় পত্র"
        return listOf(
            ExamQuestion(
                id = "${chapterId}_custom_q1",
                subjectId = subjectId,
                chapterId = chapterId,
                paper = paper,
                questionText = "$chapterTitle ($paperLabel) অধ্যায়ের মৌলিক ধারণা ও সংজ্ঞা আয়ত্ত করার ক্ষেত্রে কোনটি সবচেয়ে গুরুত্বপূর্ণ?",
                options = listOf("কেবল মুখস্থ করা", "মূল ধারণা ও বাস্তব প্রয়োগ বোঝা", "প্রশ্ন বাদ দেওয়া", "উত্তর না দেখে অনুমান"),
                correctIndex = 1,
                explanation = "সৃজনশীল (CQ) ও বহুনির্বাচনি (MCQ) প্রশ্নের সঠিক উত্তরের জন্য মূল ধারণা বোঝা অপরিহার্য।"
            ),
            ExamQuestion(
                id = "${chapterId}_custom_q2",
                subjectId = subjectId,
                chapterId = chapterId,
                paper = paper,
                questionText = "এইচএসসি বোর্ড পরীক্ষায় '$chapterTitle' অধ্যায় থেকে উদ্দীপকভিত্তিক উচ্চতর দক্ষতা (ঘ) প্রশ্নে সাধারণত কী চাওয়া হয়?",
                options = listOf("এক শব্দের উত্তর", "যুক্তি ও বিশ্লেষণমূলক মূল্যায়ন", "শূন্যস্থান পূরণ", "বানান পরীক্ষা"),
                correctIndex = 1,
                explanation = "উচ্চতর দক্ষতা অংশে উদ্দীপকের সাথে পাঠ্যবইয়ের তথ্যের তুলনামূলক বিশ্লেষণ ও মতামত চাওয়া হয়।"
            ),
            ExamQuestion(
                id = "${chapterId}_custom_q3",
                subjectId = subjectId,
                chapterId = chapterId,
                paper = paper,
                questionText = "'$chapterTitle' অধ্যায়ের বহুনির্বাচনি (MCQ) অংশে ভালো করার কার্যকর উপায় কোনটি?",
                options = listOf("অনুশীলন না করা", "গুরুত্বপূর্ণ সূত্র, তারিখ ও ব্যতিক্রম নোট করে রিভিশন দেওয়া", "একবার পড়ে রেখে দেওয়া", "সব উত্তর একই চিহ্নিত করা"),
                correctIndex = 1,
                explanation = "নিয়মিত মডেল টেস্ট ও ভুল প্রশ্ন পুনরায় চর্চার মাধ্যমে MCQ-তে পূর্ণ নম্বর পাওয়া সহজ হয়।"
            )
        )
    }

    fun getQuestionsByIds(ids: Set<String>): List<ExamQuestion> =
        ids.mapNotNull { allById[it] }

    fun totalQuestionsCount(): Int = allById.size
}
